with unpacked as (select id, host, payload_json, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier, shiftright(status_code, 2) as status_code_high, get_json_object(payload_json, '$.user.id') as user_id from app_logs where host in ('h2', 'h1', 'h4')) select id, status_code_high, user_id, ntile(10) over (partition by tier order by status_code_high desc, id) as status_code_high_bucket, max(status_code_high) over (partition by tier) as tier_max_status_code_high from unpacked
